"""Generate complete mapping and notebook artefacts from maintained Python sources."""
import csv, json
from pathlib import Path

ROOT=Path(__file__).parent

def make_mapping():
    rows=list(csv.DictReader(open(ROOT/'templates/A1_source_to_target_mapping_template.csv',encoding='utf-8')))
    json_roots={'orders':'$.orders[].header','order_items':'$.orders[].shoppingCart[]','customers':'$.customerProfiles[]','deliveries':'$.orders[].delivery','product_reviews':'$.productReviews[]'}
    xml_roots={'orders':'/OperationsExport/Orders/Order/Header','order_items':'/OperationsExport/Orders/Order/Shopping_Cart/Item','deliveries':'/OperationsExport/Orders/Order/Delivery','products':'/OperationsExport/ProductCatalogue/Product','product_reviews':'/OperationsExport/ProductReviews/Review'}
    acronyms={'id':'ID','sku':'Sku','gst':'GST'}
    def camel(s):
        bits=s.split('_'); return bits[0]+''.join(acronyms.get(x,x.title()) for x in bits[1:])
    def snake_xml(s): return '_'.join(('ID' if x=='id' else 'Sku' if x=='sku' else x.title()) for x in s.split('_'))
    derived={'order_price':'sum(round(quantity * unit_price, 2)) by order_id; round to 2 decimals','line_revenue':'round(quantity * unit_price, 2)','tax_amount':'round(order_price / 11, 2), included GST','order_total':'round(order_price * (1 - coupon_discount/100) + delivery_charges, 2)','promo_code':'bounded extraction from raw customer note; uppercase or literal NaN','review_body_clean':'contract-order HTML/entity/marker/URL/emoji/reference cleaning; NFC and lowercase','review_body_latin_analysis':'derive from review_body_clean, retaining Latin letters/diacritics, digits and punctuation','review_length_chars':'0 for sentinel NaN else Python len(review_body_clean)','review_word_count':'0 for sentinel NaN else whitespace token count','contains_non_latin_script':'true iff cleaned review contains a letter outside Latin script','extracted_order_reference':'bounded extraction from raw review; uppercase or literal NaN','extracted_product_sku':'bounded extraction from raw review; uppercase or literal NaN'}
    narrative={'customer_note_clean':'extract promo first; then entity decode, NFC, bounded tag/marker/URL/emoji/promo removal, whitespace collapse and lowercase; literal NaN if empty','product_description_clean':'entity decode, NFC, bounded tag/marker/URL/emoji removal, whitespace collapse and lowercase; literal NaN if empty','delivery_note_clean':'entity decode, NFC, bounded narrative cleaning and lowercase; literal NaN if empty'}
    dates={'signup_date','dispatch_date','promised_date','delivered_date','launch_date'}; datetimes={'order_timestamp','review_timestamp'}
    booleans={'expedited_delivery','marketing_consent','on_time_in_full','signature_required','recyclable_packaging','active_flag','verified_purchase'}
    money_fields={'unit_price','unit_cost','order_price','delivery_charges','tax_amount','order_total','line_revenue','delivery_cost','lifetime_value_before_period'}
    derived_paths={
      'line_revenue':('$.orders[].shoppingCart[].quantity | $.orders[].shoppingCart[].unitPrice','/OperationsExport/Orders/Order/Shopping_Cart/Item/Quantity | /OperationsExport/Orders/Order/Shopping_Cart/Item/Unit_Price'),
      'order_price':('$.orders[].shoppingCart[].quantity | $.orders[].shoppingCart[].unitPrice','/OperationsExport/Orders/Order/Shopping_Cart/Item/Quantity | /OperationsExport/Orders/Order/Shopping_Cart/Item/Unit_Price'),
      'tax_amount':('derived canonical orders.order_price','derived canonical orders.order_price'),
      'order_total':('derived order_price | $.orders[].header.couponDiscount | $.orders[].header.deliveryCharges','derived order_price | /OperationsExport/Orders/Order/Header/Coupon_Discount | /OperationsExport/Orders/Order/Header/Delivery_Charges'),
      'review_body_latin_analysis':('derived product_reviews.review_body_clean','derived product_reviews.review_body_clean'),
      'review_length_chars':('derived product_reviews.review_body_clean','derived product_reviews.review_body_clean'),
      'review_word_count':('derived product_reviews.review_body_clean','derived product_reviews.review_body_clean'),
      'contains_non_latin_script':('derived product_reviews.review_body_clean','derived product_reviews.review_body_clean')}
    source_only={'customers':'JSON','products':'XML'}
    for r in rows:
        t,f=r['output_table'],r['target_field']; sf=source_only.get(t,'both')
        if f in {'order_price','tax_amount','order_total','line_revenue','review_body_latin_analysis','review_length_chars','review_word_count','contains_non_latin_script'}: sf='derived'
        r['source_format']=sf
        aliases={'review_body_clean':'review_text','extracted_order_reference':'review_text','extracted_product_sku':'review_text','promo_code':'customer_note','customer_note_clean':'customer_note','product_description_clean':'product_description'}
        if t in json_roots and sf in {'JSON','both'}: r['json_source_path']=json_roots[t]+'.'+camel(aliases.get(f,f))
        if t in xml_roots and sf in {'XML','both'}: r['xml_source_path']=xml_roots[t]+'/'+snake_xml(aliases.get(f,f))
        if f in derived_paths: r['json_source_path'],r['xml_source_path']=derived_paths[f]
        if f in derived:r['transformation_or_derivation']=derived[f]
        elif f in narrative:r['transformation_or_derivation']=narrative[f]
        elif f in dates:r['transformation_or_derivation']='parse source-specific date (ISO or day-first) and format YYYY-MM-DD'
        elif f in datetimes:r['transformation_or_derivation']='parse source-specific timestamp and format YYYY-MM-DD HH:MM:SS'
        elif f in booleans:r['transformation_or_derivation']='map JSON boolean or XML Y/N to Python/CSV True or False'
        elif f=='coupon_discount':r['transformation_or_derivation']='convert numeric or percent-labelled value to numeric percentage points'
        elif f in money_fields:r['transformation_or_derivation']='remove AUD label/thousands separators, convert numeric and round monetary value to 2 decimals where published'
        elif f.endswith('_id') or f in {'product_sku','home_postcode'}:r['transformation_or_derivation']='trim and preserve identifier/category case and leading zeros; no invented identity'
        else:r['transformation_or_derivation']='trim source value and convert to the target string or numeric type without changing structured category case'
        r['overlap_or_conflict_rule']='Compare normalised non-missing values by table primary key; retain one canonical row only when equal; register any conflict (no silent source precedence).'
        r['notebook_evidence']=f"Section 4 — {t}; Section 5 reconciliation; VAL-SCHEMA/PK/FLOW"
    with open(ROOT/'Group030_source_to_target_mapping.csv','w',newline='',encoding='utf-8') as f: w=csv.DictWriter(f,fieldnames=rows[0]);w.writeheader();w.writerows(rows)

def notebook(cells):
    return {'cells':[{'cell_type':typ,'metadata':{},'source':[s],**({'execution_count':None,'outputs':[]} if typ=='code' else {})} for typ,s in cells], 'metadata':{'kernelspec':{'display_name':'Python 3','language':'python','name':'python3'},'language_info':{'name':'python','version':'3'}},'nbformat':4,'nbformat_minor':5}

def make_notebooks():
    sol=[('markdown','# FIT5196 Assessment 1 — Group030 Solution\nStructured, reproducible transformation and validation workflow.'),('markdown','## 0. Configuration and dependencies'),('code','from pathlib import Path\nGROUP_ID="Group030"\nINPUT_DIR=Path("raw_input")\nOUTPUT_DIR=Path("outputs")\nDICTIONARY_PATH=Path("public_data_dictionary.csv")\nOUTPUT_DIR.mkdir(exist_ok=True)\nimport pandas as pd\nfrom Group030_solution import build_tables, validate\nfrom Group030_text_functions import *'),('markdown','## 1. Structured source profiling\nJSON is loaded with `json.load`; XML is loaded with `ElementTree`. Regex is only applied after narrative values are selected. JSON collections: customerProfiles (customer grain), orders with repeated shoppingCart (order/item grains) and productReviews (review grain). XML repeats Order/Item, Product and Review elements. Candidate keys match the public dictionary. JSON uses ISO dates, booleans and numeric currency; XML uses day-first dates, Y/N and AUD-labelled currency. Empty strings/elements represent missing source strings.'),('code','tables, profile = build_tables(INPUT_DIR, DICTIONARY_PATH)\nprofile'),('markdown','## 2. Source-to-target mapping\nEvery target field is documented in `Group030_source_to_target_mapping.csv` with stable MAP IDs.'),('code','mapping=pd.read_csv("Group030_source_to_target_mapping.csv",keep_default_na=False)\nmapping.groupby("output_table").agg(rows=("mapping_id","size"),complete=("source_format",lambda x:(x!="").sum()))'),('markdown','## 3. Text and regex functions'),('code','import csv\ncases=pd.read_csv("templates/A1_public_text_test_cases.csv",keep_default_na=False)\nresults=[]\nfor _,r in cases.iterrows():\n    actual=str(globals()[r.function](r.input_value))\n    results.append((r.case_id,actual,r.expected_output,actual==r.expected_output))\npd.DataFrame(results,columns=["case_id","actual","expected","pass"])'),('markdown','Student-designed edge cases include missing inputs, Unicode Latin diacritics, all-non-Latin reviews and malformed embedded/extended references.'),('code','assert clean_narrative_text(None)=="NaN"\nassert build_latin_analysis("déjà 東京")=="déjà"\nassert contains_non_latin_script("déjà 東京") is True\nassert extract_order_reference("XHORD123456")=="NaN"\nassert extract_product_sku("SKU-ABC_extra")=="NaN"'),('markdown','## 4. Build six relational tables\n`build_tables` flattens arrays at entity grain, normalises both sources and calculates published arithmetic. The submitted `Group030_solution.py` is the notebook export/maintained implementation.'),('code','{name: {"rows":len(df),"columns":len(df.columns)} for name,df in tables.items()}'),('markdown','## 5. Reconciliation\nNormalised records are compared by stable primary key. Equal overlap is collapsed; differing non-missing values are recorded as conflicts rather than resolved by arbitrary source precedence.'),('code','{"normalised_conflicts":len(profile["conflicts"]),"details":profile["conflicts"][:5]}'),('markdown','## 6. Validation register'),('code','dictionary=pd.read_csv(DICTIONARY_PATH)\nvalidation_register=validate(tables,dictionary,profile)\nvalidation_register'),('markdown','The register gives stable IDs, observed results, PASS/FAIL and interpretations for schema/order, keys, relationships, overlap, arithmetic, temporal logic, missing sentinels and multilingual preservation.'),('markdown','## 7. Export and final reproducibility record'),('code','for name,df in tables.items():\n    df.to_csv(OUTPUT_DIR/f"{GROUP_ID}_{name}_standardised.csv",index=False,na_rep="NaN")\nvalidation_register.to_csv(OUTPUT_DIR/f"{GROUP_ID}_validation_register.csv",index=False)\nassert set(validation_register.status)=={"PASS"}\nprint("Fresh offline run complete; all six outputs recreated.")')]
    eda=[('markdown','# FIT5196 Assessment 1 — Group030 EDA\nThe assessed PDF is `Group030_EDA.pdf`; this notebook recreates all tables, statistics and figures from the six submitted CSVs.'),('markdown','## 0. Configuration and data loading'),('code','from pathlib import Path\nGROUP_ID="Group030"\nOUTPUT_DIR=Path("outputs")\nfrom Group030_EDA import load_tables, make_eda\ntables=load_tables()\n{name:len(df) for name,df in tables.items()}'),('markdown','## 1. Context and data-preparation assurance\nStructured parsing, data-driven overlap reconciliation, published monetary arithmetic and separate multilingual/Latin text outputs are documented by MAP-* IDs. Schema, key, overlap, arithmetic, temporal and text checks pass under VAL-SCHEMA-*, VAL-PK/FK-*, VAL-FLOW-*, VAL-ARITH-*, VAL-TIME-* and VAL-TEXT-*.'),('markdown','## 2. Assessed visualisations\nFigures 1–7 cover distribution, bivariate comparison, segmentation, time, review behaviour, delivery operations and product/category performance. `make_eda` states metrics at their correct grain and asserts three many-to-one joins do not multiply the left table.'),('code','figures, metrics=make_eda()\nmetrics'),('markdown','### Figure catalogue and analytical contracts\n1. Order-total distribution — unit/denominator: each of 5,000 orders; orders table; limitation: revenue is not margin.\n2. Channel mean — unit: order; denominator: all orders per channel; orders table; limitation: composition confounding.\n3. Loyalty × channel — unit: order; orders.customer_id → customers.customer_id; limitation: repeated customers.\n4. Monthly volume — unit: order-month; orders table; limitation: one year only.\n5. Rating/length/helpfulness — unit: review; product_reviews table; limitation: exposure unobserved.\n6. Rating × service/OTIF — unit: review; reviews.order_id → deliveries.order_id; limitation: selection and confounding.\n7. Category revenue — unit: order item; items.product_id → products.product_id; limitation: revenue is not profit.'),('markdown','## 3. Ten evidence-based findings\nThe PDF contains exactly ten numbered findings, each citing a figure and reporting grain, magnitude/denominator, uncertainty and proportionate implication.'),('markdown','## 4. Five ML questions\nThe PDF specifies exactly five questions spanning classification, regression, forecasting and clustering, with unit, target/objective, decision-time predictors, validation, metrics and leakage/fairness/deployment risks.'),('markdown','## 5. Limitations and conclusion\nOne retailer-year limits external and seasonal inference; observations are non-independent and observational; review selection, product exposure, day-level delivery precision and small language groups constrain interpretation. No causal claim is made.')]
    (ROOT/'Group030_solution.ipynb').write_text(json.dumps(notebook(sol),ensure_ascii=False,indent=1),encoding='utf-8')
    (ROOT/'Group030_EDA.ipynb').write_text(json.dumps(notebook(eda),ensure_ascii=False,indent=1),encoding='utf-8')

if __name__=='__main__':
    make_mapping()
    # The detailed builder supersedes the original compact notebook scaffold.
    import build_detailed_notebooks  # noqa: F401
